INSERT INTO legal_referentials (id, workspace_id, legal_domain, referential_type, entry_key, value_json, label, country, is_system, is_active, source_ref, description, updated_at, updated_by)
VALUES ('f1100001-0000-0000-0000-0000000001a0', NULL, 'DROIT_IMMIGRATION', 'IM21_VALIDITY_CRITERES', 'IM21_REGULARITE_SEJOUR_FR', '{"binaire":true,"description":"Le demandeur est-il en situation régulière au moment du dépôt (titre en cours de validité, récépissé, ou pré-droit ouvert) ?"}', 'Régularité du séjour au moment du dépôt', 'FRANCE', true, true, 'Art. R.431-2 CESEDA', 'Critère binaire F-IM-21 — Vérifie la régularité du séjour au moment du dépôt de la demande de titre. Utilisé par la checklist procédurale F-96 pour les dossiers immigration FR (VERIFIED/NON_COMPLIANT/TO_CHECK).', NOW(), NULL);

INSERT INTO legal_referentials (id, workspace_id, legal_domain, referential_type, entry_key, value_json, label, country, is_system, is_active, source_ref, description, updated_at, updated_by)
